-- Ensure table supports variants and enhanced composition
ALTER TABLE IF EXISTS public.medicines 
  ADD COLUMN IF NOT EXISTS active_ingredient TEXT,
  ADD COLUMN IF NOT EXISTS composition TEXT,
  ADD COLUMN IF NOT EXISTS dosage_form TEXT,
  ADD COLUMN IF NOT EXISTS route TEXT,
  ADD COLUMN IF NOT EXISTS combination_ingredients TEXT,
  ADD COLUMN IF NOT EXISTS reference_source TEXT,
  ADD COLUMN IF NOT EXISTS is_prescription_required BOOLEAN DEFAULT true,
  ADD COLUMN IF NOT EXISTS variants JSONB;

